# System fields every Zoho CRM record module returns.
_COMMON_COLUMNS: dict[str, str] = {
    "id": "Unique record identifier, generated by Zoho CRM.",
    "Owner": "User the record is assigned to, as a lookup object with id, name, and email.",
    "Created_By": "User who created the record, as a lookup object with id, name, and email.",
    "Modified_By": "User who last updated the record, as a lookup object with id, name, and email.",
    "Created_Time": "Timestamp the record was created, in the org's time zone.",
    "Modified_Time": "Timestamp the record was last updated, in the org's time zone.",
    "Last_Activity_Time": "Timestamp of the most recent activity logged against the record.",
    "Tag": "Tags applied to the record.",
    "$approval_state": "Approval state of the record (approved, pending, or rejected).",
}


def _columns(**extra: str) -> dict[str, str]:
    return {**_COMMON_COLUMNS, **extra}


